#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> graph(N);
    for (int i = 0; i < N - 1; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        graph[x].push_back(y);
        graph[y].push_back(x);
    }

    auto bfs = [&](int start, vector<int>* parent) {
        vector<int> dist(N, -1);
        if (parent) parent->assign(N, -1);

        queue<int> q;
        q.push(start);
        dist[start] = 0;
        int farthest = start;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (dist[u] > dist[farthest]) farthest = u;

            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    if (parent) (*parent)[v] = u;
                    q.push(v);
                }
            }
        }

        return pair<int, vector<int>>(farthest, move(dist));
    };

    int endpointA = bfs(0, nullptr).first;
    vector<int> parent;
    auto [endpointB, distances] = bfs(endpointA, &parent);
    int diameter = distances[endpointB];

    vector<int> path;
    for (int u = endpointB; u != -1; u = parent[u]) {
        path.push_back(u);
    }
    reverse(path.begin(), path.end());

    long long ways = 0;

    if (diameter % 2 == 0) {
        int center = path[diameter / 2];
        int radius = diameter / 2;
        long long total = 0, sumSquares = 0;

        for (int neighbor : graph[center]) {
            long long count = 0;
            vector<tuple<int, int, int>> stack;
            stack.emplace_back(neighbor, center, 1);

            while (!stack.empty()) {
                auto [u, p, depth] = stack.back();
                stack.pop_back();

                if (depth == radius) {
                    ++count;
                    continue;
                }

                for (int v : graph[u]) {
                    if (v != p) stack.emplace_back(v, u, depth + 1);
                }
            }

            total += count;
            sumSquares += count * count;
        }

        ways = (total * total - sumSquares) / 2;
    } else {
        int leftCenter = path[diameter / 2];
        int rightCenter = path[diameter / 2 + 1];
        int radius = diameter / 2;

        auto countSide = [&](int start, int blocked) {
            long long count = 0;
            vector<tuple<int, int, int>> stack;
            stack.emplace_back(start, blocked, 0);

            while (!stack.empty()) {
                auto [u, p, depth] = stack.back();
                stack.pop_back();

                if (depth == radius) {
                    ++count;
                    continue;
                }

                for (int v : graph[u]) {
                    if (v != p) stack.emplace_back(v, u, depth + 1);
                }
            }

            return count;
        };

        ways = countSide(leftCenter, rightCenter) *
               countSide(rightCenter, leftCenter);
    }

    cout << diameter + 1 << '\n' << ways << '\n';
    return 0;
}
